-- BEGIN outputs/2026-10-10-n1-pattern-correction/n1-pattern-update.sql SHA256 0a89f6ef87739caf3276a7e6d7a5c07efd23e9702325f0a798af32f0be1f4f82
-- Task-owned Japanese grammar pattern correction. No learner history or source-team writes.
SET NAMES utf8mb4;
-- [JLAS-W0108] 2026-11-01 (owner): the LP-OWNED content_source provenance rows are gone, so each patched grammar point
-- is found by its lesson source_code and order_index (the same pair the v8 supplement used to insert it).
CREATE TEMPORARY TABLE owned_grammar_pattern_patch (stable_code VARCHAR(64) PRIMARY KEY, lesson_source_code VARCHAR(100) COLLATE utf8mb4_unicode_ci NOT NULL, order_index INT NOT NULL, old_pattern VARCHAR(255) NOT NULL, new_pattern VARCHAR(255) NOT NULL);
CREATE TEMPORARY TABLE owned_grammar_pattern_guard (ok INT NOT NULL CHECK (ok=1));
START TRANSACTION;
UPDATE grammar_point g JOIN lesson l ON l.id=g.lesson_id JOIN owned_grammar_pattern_patch p ON p.lesson_source_code=l.source_code AND p.order_index=g.order_index JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id SET g.pattern=p.new_pattern WHERE t.source_code=CONVERT(0x4c502d4f574e45442d5348494e4b414e5a454e2d4d41535445522d4e31 USING utf8mb4) COLLATE utf8mb4_0900_as_cs AND BINARY g.pattern=BINARY p.old_pattern;
COMMIT;
-- END outputs/2026-10-10-n1-pattern-correction/n1-pattern-update.sql

