('JG-603137e58e-O02', 'JG-603137e58e', 'N1', 'ORDER', 'ORDER', 2, '上がりこそすれ、 / ないだろう。 / 値段は / 下がることは', NULL, NULL, NULL, '["上がりこそすれ、","ないだろう。","値段は","下がることは"]', '[2,0,3,1]', NULL, NULL, 'Giá chỉ có tăng chứ chắc không giảm.', 'AI_CHECKED', 1, 'a742906c4fec'),
('JG-603137e58e-X01', 'JG-603137e58e', 'N1', 'EXTRA', 'FILL', 1, '練習すれば、上手になり（　　）、へたにはならない。', NULL, '["がてら","ながらの","こそすれ","ずくめ"]', 2, NULL, NULL, NULL, NULL, 'Luyện tập thì chỉ giỏi lên chứ không kém đi.', 'AI_CHECKED', 1, 'a742906c4fec'),
