('JG-7aad04d3c1-F02', 'JG-7aad04d3c1', 'N1', 'FILL', 'FILL_TEXT', 2, '両国の合意の＿＿、活動が始まった。', NULL, NULL, NULL, NULL, NULL, 'もとに', NULL, 'Hoạt động bắt đầu trên cơ sở thoả thuận của hai nước.', 'AI_CHECKED', 1, 'a742906c4fec'),
('JG-7aad04d3c1-O01', 'JG-7aad04d3c1', 'N1', 'ORDER', 'ORDER', 1, 'もとで / 私は / 研究を続けている。 / 指導教官の', NULL, NULL, NULL, '["もとで","私は","研究を続けている。","指導教官の"]', '[1,3,0,2]', NULL, NULL, 'Tôi đang tiếp tục nghiên cứu dưới sự hướng dẫn của giáo sư.', 'AI_CHECKED', 1, 'a742906c4fec'),
